import{_ as r,o as d,c as e,ag as a,j as s}from"./chunks/framework.KxDd3USm.js";const C=JSON.parse('{"title":"09.2 CPU、存储体系与主存编址 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"09-计算机系统基础/02-CPU与主存.md","filePath":"09-计算机系统基础/02-CPU与主存.md"}'),l={name:"09-计算机系统基础/02-CPU与主存.md"},o={class:"fig"},i={"data-figure-id":"figure-26",viewBox:"0 0 700 250",width:"100%",style:{"max-width":"700px"},role:"img","aria-label":"存储体系层次图：寄存器、Cache、主存、外存从上到下容量逐渐增大、速度逐渐变慢、每位成本逐渐降低。Cache 位于寄存器和主存之间，用于利用程序的时间局部性和空间局部性。"};function n(p,t,c,h,_,g){return d(),e("div",null,[t[2]||(t[2]=a('<h1 id="_09-2-cpu、存储体系与主存编址-★★★" tabindex="-1">09.2 CPU、存储体系与主存编址 ★★★ <a class="header-anchor" href="#_09-2-cpu、存储体系与主存编址-★★★" aria-label="Permalink to &quot;09.2 CPU、存储体系与主存编址 ★★★&quot;">​</a></h1><p>CPU 主要由<strong>运算器、控制器、寄存器组和内部总线</strong>组成。</p><table tabindex="0"><thead><tr><th>部件</th><th>作用</th><th>关键词</th></tr></thead><tbody><tr><td>ALU（算术逻辑单元）</td><td>做算术与逻辑运算</td><td>真正“算”</td></tr><tr><td>AC（累加寄存器）</td><td>暂存操作数和运算结果</td><td>ALU 工作区</td></tr><tr><td>DR/MDR（数据缓冲寄存器）</td><td>暂存从主存读出或要写入主存的数据</td><td>数据中转站</td></tr><tr><td>PSW（程序状态字）</td><td>保存零、进位、溢出、中断允许等状态</td><td>状态标志</td></tr><tr><td>PC（程序计数器）</td><td>保存<strong>下一条</strong>要取的指令地址</td><td>下一条在哪</td></tr><tr><td>IR（指令寄存器）</td><td>保存<strong>当前正在执行</strong>的指令</td><td>当前是什么</td></tr><tr><td>MAR/AR（地址寄存器）</td><td>保存当前访问的主存地址</td><td>去哪里读写</td></tr><tr><td>指令译码器</td><td>解释操作码</td><td>要做什么</td></tr><tr><td>时序部件</td><td>发出有先后次序的控制信号</td><td>什么时候做</td></tr></tbody></table><p>指令周期通常经历：<strong>取指 → 分析/译码 → 执行</strong>。冯·诺依曼机的指令和数据都以二进制存入同一存储器，CPU 不是靠“长相”区分它们，而是靠<strong>所处的指令周期阶段</strong>：取指阶段读到的是指令，执行阶段按指令要求读到的是数据。</p><p><strong>反例</strong>：“PC 保存当前指令”是错的。当前指令在 IR，PC 通常已经指向下一条指令。“地址寄存器保存数据”也错，MAR 保存地址，MDR 保存数据。</p><h3 id="_3-1-常见性能指标" tabindex="-1">3.1 常见性能指标 <a class="header-anchor" href="#_3-1-常见性能指标" aria-label="Permalink to &quot;3.1 常见性能指标&quot;">​</a></h3><ul><li>时钟周期 T = 1 / 主频 f；</li><li>CPI = 总时钟周期数 / 指令条数；</li><li>CPU 执行时间 = 指令条数 × CPI × 时钟周期；</li><li>MIPS = 主频 / (CPI × 10^6)，主频单位为 Hz；</li><li>带宽 = 数据量 / 传输时间。</li></ul><p>例：某处理器主频 2 GHz，平均 CPI=4，执行 5×10^8 条指令：</p><p>CPU 时间 = 5×10^8 × 4 / (2×10^9) = <strong>1 s</strong>。</p><p>反向验算：2 GHz 在 1 秒内给出 2×10^9 个周期；5×10^8 条×4 周期/条也正好是 2×10^9 个周期。</p><p><strong>应试动作</strong>：看到“下一条地址”选 PC，“当前指令”选 IR，“算术逻辑”选 ALU，“主存地址”选 MAR，“主存数据”选 MDR。性能计算先统一 Hz、秒、Byte/bit。</p><hr><h2 id="第四节-存储体系与主存编址-★★★" tabindex="-1">第四节 存储体系与主存编址 ★★★ <a class="header-anchor" href="#第四节-存储体系与主存编址-★★★" aria-label="Permalink to &quot;第四节 存储体系与主存编址 ★★★&quot;">​</a></h2><h3 id="_4-1-为什么分层" tabindex="-1">4.1 为什么分层 <a class="header-anchor" href="#_4-1-为什么分层" aria-label="Permalink to &quot;4.1 为什么分层&quot;">​</a></h3><p>理想存储器要又快、又大、又便宜，但现实中三者不能同时满足，所以按层次组合：</p><p><strong>寄存器 → Cache → 主存 → 外存</strong></p><p>从左到右：速度变慢、容量变大、每位成本降低。分层能奏效，是因为程序具有<strong>局部性</strong>：</p><ul><li>时间局部性：刚访问过的内容很快又访问，如循环中的指令；</li><li>空间局部性：访问某地址后很快访问邻近地址，如顺序扫描数组。</li></ul>',18)),s("figure",o,[(d(),e("svg",i,[...t[0]||(t[0]=[a('<defs><marker id="marr" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="var(--ink)"></path></marker></defs><text x="40" y="30" class="t">离 CPU 越近：更快、更小、更贵</text><text x="440" y="30" class="t">离 CPU 越远：更慢、更大、更便宜</text><path d="M350 45V220" class="e" marker-end="url(#marr)"></path><path d="M205 62H495L455 102H245z" class="b"></path><text x="318" y="88" class="t">寄存器</text><path d="M175 112H525L480 152H220z" class="b"></path><text x="328" y="138" class="t">Cache</text><path d="M135 162H565L515 202H185z" class="b"></path><text x="328" y="188" class="t">主存</text><path d="M95 212H605L550 247H150z" class="b"></path><text x="328" y="235" class="t">外存</text><text x="34" y="142" class="s">容量 ↑</text><text x="34" y="160" class="s">访问时间 ↑</text><text x="570" y="142" class="s">每位成本 ↓</text>',15)])])),t[1]||(t[1]=s("figcaption",null,"分层不是简单排序：Cache 靠局部性把常用主存块留在更快的一层。",-1))]),t[3]||(t[3]=a(`<h3 id="_4-2-常见存储器" tabindex="-1">4.2 常见存储器 <a class="header-anchor" href="#_4-2-常见存储器" aria-label="Permalink to &quot;4.2 常见存储器&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>特点</th><th>常见用途</th></tr></thead><tbody><tr><td>SRAM</td><td>不需刷新、快、贵、集成度低</td><td>Cache</td></tr><tr><td>DRAM</td><td>需刷新、较慢、便宜、集成度高</td><td>主存</td></tr><tr><td>ROM</td><td>断电不丢，通常只读</td><td>固件</td></tr><tr><td>EEPROM</td><td>可电擦写，常按字节操作</td><td>配置数据</td></tr><tr><td>Flash</td><td>电擦写，通常按块擦除</td><td>SSD、U 盘</td></tr><tr><td>相联存储器</td><td>按内容检索</td><td>Cache/TLB 中的快速匹配</td></tr></tbody></table><p><strong>反例</strong>：RAM 的“随机”不是说数据随机，而是任一地址的访问时间近似相同。磁盘是直接存取，不是严格随机存取；磁带才是典型顺序存取。</p><h3 id="_4-3-主存编址与芯片扩展" tabindex="-1">4.3 主存编址与芯片扩展 <a class="header-anchor" href="#_4-3-主存编址与芯片扩展" aria-label="Permalink to &quot;4.3 主存编址与芯片扩展&quot;">​</a></h3><p>通用形式：</p><ul><li>存储单元数 = 最大地址 − 最小地址 + 1；</li><li>总容量 = 存储单元数 × 每单元位数；</li><li>所需芯片数 = 总容量 / 单片容量；</li><li>若位宽和字数都要扩展：芯片数 = 字数扩展倍数 × 位数扩展倍数。</li></ul><p>例：地址 <code>4000H～7FFFH</code> 按字节编址：</p><p>单元数 = <code>7FFFH − 4000H + 1 = 4000H = 2^14</code> 个字节，容量 = <strong>16 KiB</strong>。</p><p>若用 <code>4K×8 bit</code> 芯片组成 <code>16K×16 bit</code> 存储器：</p><ul><li>字数扩展：16K/4K=4；</li><li>位宽扩展：16/8=2；</li><li>总片数：4×2=<strong>8 片</strong>。</li></ul><p>反向验证：8×4K×8 bit = 256 Kbit；目标 16K×16 bit = 256 Kbit，容量相等。</p><h4 id="非整齐边界的十六进制容量" tabindex="-1">非整齐边界的十六进制容量 <a class="header-anchor" href="#非整齐边界的十六进制容量" aria-label="Permalink to &quot;非整齐边界的十六进制容量&quot;">​</a></h4><p>真题不一定把首尾地址放在 <code>0000H</code>、<code>FFFFH</code> 这类整齐边界。例：地址范围 <code>B3000H～DABFFH</code>，按字节编址，求容量。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  DABFFH</span></span>
<span class="line"><span>− B3000H</span></span>
<span class="line"><span>---------</span></span>
<span class="line"><span>  27BFFH</span></span>
<span class="line"><span>+      1</span></span>
<span class="line"><span>---------</span></span>
<span class="line"><span>  27C00H</span></span></code></pre></div><p>所以单元数为 <code>27C00H</code>。换成 KiB 时可先转十进制：</p><p><code>27C00H = 2×16^4 + 7×16^3 + 12×16^2 = 162816 B = 159 KiB</code>。</p><p>再用分段法交叉验证：</p><ul><li><code>B3000H～BFFFFH</code>：<code>D000H = 52 KiB</code>；</li><li><code>C0000H～CFFFFH</code>：64 KiB；</li><li><code>D0000H～DABFFH</code>：<code>AC00H = 43 KiB</code>；</li><li>合计 <code>52+64+43=159 KiB</code>，一致。</li></ul><p><strong>反例</strong>：直接算“末地址−首地址”会少 1 个单元；本题若忘记 <code>+1</code>，就得到 <code>27BFFH</code>，无法整除成正确容量。</p><p><strong>应试动作</strong>：地址范围一定写“末−首+1”；先看“按字节还是按字编址”；芯片题分别算字数倍数和位宽倍数，不能只拿总 bit 相除后就结束——虽然片数可能相同，但连接方式还要分组。</p><hr>`,21))])}const b=r(l,[["render",n]]);export{C as __pageData,b as default};
